  async function hydrateOverview(projectId, options = {}) { const id = Number(projectId), repaint = options.repaint !== false; let load = recentLoads.get(id); if (!load) { load = api(`/api/projects/${id}/site-visits`, { redirectOnUnauthorized: false }).then(payload => { rememberRecent(id, payload?.recent || []); return payload; }).catch(() => null).finally(() => recentLoads.delete(id)); recentLoads.set(id, load); } const payload = await load; if (repaint) repaintOverview(id); return payload; }
