  document.addEventListener('click', event => { if (event.target.closest('#logout-button,#profile-logout-button,#subscription-lock-logout')) { if(active?.mode==='review')cacheReviewDraft();else cacheDraftInput(); stopVoice(); active = null; openSequence++; } }, true);
  window.addEventListener('pagehide', stopVoice); window.addEventListener('storage', event => { if (['pdl-company-id', 'pdl-role'].includes(event.key)) { stopVoice(); if (dialog?.open) dialog.close(); active = null; openSequence++; } });
